<script setup lang="ts">
import {computed,ref,shallowRef,watch,onUnmounted} from 'vue';import {createSensitiveJournal} from './minutes-sensitive-journal';
import Icon from '../../shared/Icon.vue';import type {MinutesSourceLabel} from './useMinutesSourceLabels';
import {useApplication} from '../../application';import type {MinutesCurrent} from '../../shared/api/minutes-saved';import type {components} from '../../shared/api/generated';import {ApiError} from '../../shared/api/client';
type Settings=components['schemas']['SavedSettings'];type Item={locatorId:string;category:string;reason:string|null};type SourceTarget={kind:'BODY'|'ELEMENT'|'SET';id:string;locatorId:string};
const props=defineProps<{meetingId:string;current:MinutesCurrent;locked:boolean;owner:boolean;sourceLabels?:Record<string,MinutesSourceLabel>;saveSelection?:(fields:Record<string,unknown>)=>Promise<string|null>}>(),emit=defineEmits<{source:[target:SourceTarget];denied:[cause:unknown]}>(),app=useApplication();
const journal=app.journals?createSensitiveJournal(app.journals):null;let recovered=false;
const settings=shallowRef<Settings|null>(null),base=shallowRef<Settings|null>(null),chosen=ref<string[]>([]),error=ref(''),loading=ref(false),saving=ref(false),readReady=ref(false),page=ref(0),reasons=shallowRef<Record<string,string|null>>({});let epoch=0,readEpoch=0,controller:AbortController|null=null;
const key=(category:string,locatorId:string)=>JSON.stringify([category,locatorId]);const keys=(v:Settings|null)=>(v?.items??[]).map(x=>key(x.category,x.locator_id));
const dirty=computed(()=>!!base.value&&JSON.stringify([...keys(base.value)].sort())!==JSON.stringify([...chosen.value].sort()));
const conflict=computed(()=>dirty.value&&!!settings.value&&base.value?.exclusionRevision?.id!==settings.value.exclusionRevision?.id);
const choices=computed(()=>{
 const items=new Map<string,{locatorId:string;category:string;key:string;savedOnly:boolean}>();
 function add(category:string,locatorId:string,savedOnly:boolean){
  const k=key(category,locatorId);if(!items.has(k))items.set(k,{category,locatorId,key:k,savedOnly});
 }
 for(const entry of props.current.sensitive)for(const locatorId of entry.locatorIds)add(entry.category,locatorId,false);
 for(const saved of [base.value,settings.value])for(const item of saved?.items??[])add(item.category,item.locator_id,true);
 for(const k of chosen.value){const [category,id]=JSON.parse(k);add(category,id,true);}
 return [...items.values()];
});
const labels:Record<string,string>={INTERNAL_BUSINESS_DATA:'内部经营数据',POLITICAL_SENSITIVE:'政治敏感内容'},all=computed(()=>choices.value.length>0&&choices.value.every(x=>chosen.value.includes(x.key))),mixed=computed(()=>!all.value&&chosen.value.length>0);
function toggleAll(checked:boolean){chosen.value=checked?choices.value.map(x=>x.key):[];}
function target(locatorId:string):SourceTarget|null{const e=props.current.evidence.find(e=>e.locator_id===locatorId);return e?.element_id?{kind:'ELEMENT',id:e.element_id,locatorId}:e?.minutes_revision_id?{kind:'BODY',id:e.minutes_revision_id,locatorId}:props.current.setId&&props.current.sensitive.some(d=>d.locatorIds.includes(locatorId))?{kind:'SET',id:props.current.setId,locatorId}:null;}
const previews=shallowRef<Record<string,string>>({}),previewErrors=shallowRef<Record<string,string>>({});let previewEpoch=0,previewController:AbortController|null=null;
const projectedExcerpts=computed(()=>new Map(props.current.presentation?.sourceLabels?.filter(item=>item.excerpt!==undefined).map(item=>[item.locatorId,item.excerpt!])));
const detectedCounts=computed(()=>Object.entries(labels).map(([category,label])=>label+' '+props.current.sensitive.filter(item=>item.category===category).length+' 段').join(' · '));
async function loadPreviews(){const turn=++previewEpoch;previewController?.abort();previews.value={};previewErrors.value={};if(!app.session.current.value)return;previewController=new AbortController();const signal=previewController.signal;for(const item of choices.value.slice(page.value*20,(page.value+1)*20)){const excerpt=projectedExcerpts.value.get(item.locatorId);
 if(excerpt!==undefined){previews.value={...previews.value,[item.locatorId]:excerpt};continue;}
 const t=target(item.locatorId);if(!t){previewErrors.value={...previewErrors.value,[item.locatorId]:'当前版本没有可读取的原文关联，原排除选择继续保留。'};continue;}try{const v=await app.minutesInspection.source(props.meetingId,t.locatorId,{kind:t.kind,id:t.id},signal);if(turn!==previewEpoch||signal.aborted)return;previews.value={...previews.value,[item.locatorId]:Array.from(v.text).slice(0,240).join('')};}catch(e){if(turn!==previewEpoch||signal.aborted)return;if(e instanceof ApiError&&[401,403].includes(e.status)){journal?.clear();clear();emit('denied',e);return;}previewErrors.value={...previewErrors.value,[item.locatorId]:'原文暂不可读取，请重新核对。'};}}}
watch([()=>props.owner,()=>app.session.current.value?.actor.enterpriseId,()=>props.meetingId,()=>props.current.observation.revisionToken,()=>JSON.stringify(choices.value.slice(page.value*20,(page.value+1)*20).map(i=>i.key))],loadPreviews);
function source(locatorId:string){const t=target(locatorId);if(t)emit('source',t);else error.value='当前目录未提供可读取的关联原文；此排除项会继续保留，请明确核对后再移除。';}
function selectedItems():Item[]{return chosen.value.map(k=>{const [category,locatorId]=JSON.parse(k) as [string,string];return{locatorId,category,reason:reasons.value[k]??null};});}
function prepare(){if(!settings.value?.exclusionRevision||conflict.value||loading.value||!readReady.value)return null;return{sourceExclusionRevisionId:settings.value.exclusionRevision.id,items:selectedItems()};}
function recover(){if(recovered||!journal||!app.session.current.value)return;recovered=true;const found=journal.load(app.session.current.value.actor.enterpriseId,props.meetingId);if(found.kind==='RESTORED'){base.value=found.value.base;chosen.value=found.value.chosen;reasons.value=found.value.reasons;}else if(['INVALID','UNAVAILABLE'].includes(found.kind))error.value='排除选择恢复记录暂不可读取，请保留页面后重试。';}
function persist(){const actor=app.session.current.value?.actor.enterpriseId;if(!journal||!actor||!base.value||!recovered)return;if(dirty.value){if(journal.save(actor,props.meetingId,{base:base.value,chosen:[...chosen.value],reasons:{...reasons.value}})!=='SAVED')error.value='排除选择尚未写入恢复记录，请保留页面并重试保存。';}else journal.clear();}
watch(()=>[chosen.value,reasons.value,base.value],persist,{deep:true,flush:'post'});
function adopt(v:Settings){settings.value=v;base.value=v;chosen.value=keys(v);reasons.value=Object.fromEntries(v.items.map(i=>[key(i.category,i.locator_id),i.reason]));error.value='';}
function discard(){if(saving.value)throw new Error('请先查清原保存结果。');if(settings.value)adopt(settings.value);}
function reapply(){if(!conflict.value||!settings.value||saving.value||props.locked)return;reasons.value={...Object.fromEntries(settings.value.items.map(i=>[key(i.category,i.locator_id),i.reason])),...reasons.value};base.value=settings.value;error.value='已保留本地选择，请核对完整集合后再次保存。';}
async function save(){if(props.locked||saving.value||!props.saveSelection)return false;const scope=epoch;saving.value=true;error.value='';try{if(!await load()||scope!==epoch)return false;const fields=prepare();if(!fields||props.locked){error.value='请先核对最新排除集合与版本冲突。';return false;}const submitted=JSON.stringify(fields.items),id=await props.saveSelection(fields);if(scope!==epoch)return false;if(!id){error.value='排除选择尚未确认保存，请保留本地选择并处理原操作结果。';return false;}const v=await load();if(!v||scope!==epoch)return false;const actual=v.items.map(i=>({locatorId:i.locator_id,category:i.category,reason:i.reason}));const canonical=(items:Item[])=>JSON.stringify([...items].sort((a,b)=>key(a.category,a.locatorId).localeCompare(key(b.category,b.locatorId))));if(v.exclusionRevision?.id!==id||canonical(actual)!==canonical(JSON.parse(submitted))){error.value='已收到原操作结果，但当前排除版本已变化；本地选择保留，请重新核对。';return false;}adopt(v);return true;}catch(e){if(scope===epoch)error.value=e instanceof Error?e.message:'排除选择暂不可保存';return false;}finally{if(scope===epoch)saving.value=false;}}
async function load(){const turn=++readEpoch,scope=epoch;controller?.abort();controller=new AbortController();const signal=controller.signal;loading.value=true;readReady.value=false;try{const v=await app.minutesInspection.settings(props.meetingId,signal);if(turn!==readEpoch||scope!==epoch||signal.aborted)return null;recover();if(!base.value||!dirty.value)adopt(v);else settings.value=v;readReady.value=true;return v;}catch(e){if(turn===readEpoch&&scope===epoch&&!signal.aborted){if(e instanceof ApiError&&[401,403].includes(e.status)){journal?.clear();clear();emit('denied',e);}else error.value=e instanceof Error?e.message:'排除设置暂不可用';}return null;}finally{if(turn===readEpoch&&scope===epoch)loading.value=false;}}
function clear(){recovered=false;if(journal){const actor=app.session.current.value?.actor.enterpriseId??null;if(actor)journal.synchronize(actor,props.meetingId);else journal.clear();}previewEpoch++;previewController?.abort();previews.value={};previewErrors.value={};readReady.value=false;epoch++;readEpoch++;reasons.value={};controller?.abort();settings.value=null;base.value=null;chosen.value=[];error.value='';loading.value=false;saving.value=false;page.value=0;}
function observeSelection(){
 if(!props.owner||!app.session.current.value)return;
 recover();
 const projected=props.current.presentation?.selectedExclusions;
 if(!projected||base.value||error.value){void load();return;}
 chosen.value=projected.map(item=>key(item.category,item.locatorId));
}
async function changeSelection(item:string|null,checked:boolean){
 const scope=epoch;
 if(props.locked||loading.value||saving.value)return;
 if(!base.value){
  const observed=props.current.observation.revisionToken,latest=await load();
  if(!latest||scope!==epoch||props.locked)return;
  if(latest.observation.revisionToken!==observed){error.value='排除设置已更新，请核对最新选择后重试。';return;}
 }
 if(item===null)toggleAll(checked);
 else chosen.value=checked?[...new Set([...chosen.value,item])]:chosen.value.filter(value=>value!==item);
 await save();
}
watch(()=>[props.meetingId,app.session.current.value?.actor.enterpriseId,props.owner],()=>{clear();if(app.session.current.value){observeSelection();void loadPreviews();}},{immediate:true,flush:'sync'});
watch(()=>props.current.observation.revisionToken,observeSelection);onUnmounted(clear);defineExpose({prepare,dirty,save,discard,selectionCount:computed(()=>readReady.value||props.current.presentation?.selectedExclusions?chosen.value.length:null)});
</script>
<template><section id="minutes-category-SENSITIVE" class="minutes-elements sensitive-section min-sec card card-p"><div class="ms-h"><h3 class="ms-t">敏感信息</h3><label v-if="owner" class="select-all am-sensitive-all"><input type="checkbox" :checked="all" :indeterminate="mixed" :disabled="locked||loading||saving||!choices.length" @change="changeSelection(null,($event.target as HTMLInputElement).checked)"/>全部排除</label></div><p class="am-sensitive-intro">{{detectedCounts}}。AI 识别结果请人工核对。勾选后自动保存，下次生成时排除；原录音及转写保留，请核对关联结论和行动项是否完整。</p><p v-if="error" role="alert">{{error}} <button class="btn sm" :disabled="loading||saving" @click="load">重新读取排除设置</button></p><div v-if="conflict" class="banner warning" role="alert">服务器的排除集合已变化，本地选择已保留。请核对后决定。<button class="btn sm" :disabled="locked||saving||loading" @click="reapply">保留选择并应用到最新版本</button><button class="btn sm" :disabled="saving||loading" @click="discard">放弃本地选择</button></div><article v-for="item in choices.slice(page*20,(page+1)*20)" :key="item.key" class="sensitive-item am-sensitive-para"><div class="am-sensitive-copy"><div class="am-sensitive-text"><span class="tag outline">{{labels[item.category]??item.category}}</span><span v-if="previews[item.locatorId]" class="sensitive-excerpt">{{previews[item.locatorId]}}</span><span v-else class="small muted">{{previewErrors[item.locatorId]??'正在读取原文…'}}</span></div><p v-if="item.savedOnly" class="small muted">当前检测目录未列出此来源，已保存的排除选择继续保留；取消勾选会明确移除此项。</p><div class="am-compact-sources"><button class="am-source-tag" :class="sourceLabels?.[item.locatorId]?.kind==='material'?'am-evidence-material':'am-evidence-recording'" aria-label="查看原文" :title="sourceLabels?.[item.locatorId]?.label" @click="source(item.locatorId)"><Icon :name="sourceLabels?.[item.locatorId]?.kind==='recording'?'mic':'file'" :size="12"/><span>{{sourceLabels?.[item.locatorId]?.label??'查看原文'}}</span></button></div></div><label v-if="owner" class="am-exclude"><input type="checkbox" :checked="chosen.includes(item.key)" :value="item.key" :disabled="locked||loading||saving" @change="changeSelection(item.key,($event.target as HTMLInputElement).checked)"/>排除</label><span v-else class="small muted">{{current.presentation?.exclusions.some(x=>x.locatorId===item.locatorId&&x.category===item.category&&x.selected)?'已选择排除':'未排除'}}</span></article><p v-if="!choices.length" class="empty small">暂未识别出相关内容，请核对会议文件与背景材料。</p><div v-if="choices.length>20" class="flex"><button class="btn sm" :disabled="page===0" @click="page--">上一页</button><button class="btn sm" :disabled="(page+1)*20>=choices.length" @click="page++">下一页</button></div><div v-if="owner&&choices.length" class="between mt12"><span class="small muted">{{chosen.length}}段选择排除 · 更改后需重新生成并采用</span><span v-if="saving" role="status">正在保存…</span><button v-if="dirty&&!saving" class="btn sm" :disabled="locked||loading||!settings?.exclusionRevision||conflict" @click="save">重试保存排除选择</button></div></section></template>
<style scoped>.sensitive-section h3{margin:0}.sensitive-section [role=alert]{color:#9a3412}</style>
